sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below

    var outcome = g_form.getValue('outcome');
    var transType = g_form.getValue('transaction_type');
    var switchInd = g_scratchpad.trade_id.switch_indicator;
    var legacyStat = g_scratchpad.trade_id.legStat;
    if (outcome == 'Amend Trade') {
        //make fields visible or readonly

        if ((legacyStat == 'CODE') || (legacyStat == 'PRPR') || (legacyStat == 'PAPP') || (legacyStat == 'PCON')) {
            g_form.setReadOnly('amend_security_id', false);
            if (switchInd == 'N') {
                g_form.setDisplay('amend_switch_account', false);
            } else
                g_form.setDisplay('amend_switch_account', true);
        } else
            g_form.setReadOnly('amend_security_id', true);

        if ((legacyStat == 'CODE') || (legacyStat == 'PRPR') || (legacyStat == 'PAPP') || (legacyStat == 'PCON') || (legacyStat == 'CONF') || (legacyStat == 'CLRG')) {
            g_form.setReadOnly('amend_trade_date', false);
            g_form.setReadOnly('amend_location_code', false);
            g_form.setReadOnly('amend_customer_reference', false);
            if (switchInd == 'Y') {
                g_form.setDisplay('amend_counterparty_code', false);
            } else
                g_form.setDisplay('amend_counterparty_code', true);
            if ((transType == 'RVP') || (transType == 'DVP')) {
                g_form.setReadOnly('amend_settlement_currency', false);
            } else
                g_form.setReadOnly('amend_settlement_currency', true);
        } else {
            g_form.setReadOnly('amend_trade_date', true);
            g_form.setReadOnly('amend_location_code', true);
            g_form.setReadOnly('amend_customer_reference', true);
        }

        if ((legacyStat == 'STTS') || (legacyStat == 'STTC')) {
            g_form.setReadOnly('settlement_date', true);
            if ((transType == 'RVP') || (transType == 'DVP')) {
                g_form.setReadOnly('amend_settlement_amount', true);
            }
        }

        if (switchInd == 'Y') {
            g_form.setDisplay('amend_counterparty_reference', false);
            if ((transType == 'RVP') || (transType == 'DVP') && (legacyStat == 'STTC')) {
                //gtrr
            }
        }
    }
}
